Under Assumption ass1, 
for any $t\geqslant0$ we have
\begin{equation}

\left|\int_0^t\overline p_{0}^{(n)}(s)\mathrm{d} s\right|\lesssim \frac{1}{n} \qquad \text{and} \qquad \left|\int_0^t\overline p_{n}^{(n)}(s)\mathrm{d} s\right|\lesssim \frac{1}{n},\qquad
 n\geqslant1.
\end{equation}

Under Assumptions ass1 and ass3,  for any complex valued test function $
G\in C_0^\infty([0,+\infty)\times {\mathbb I}\times\mathbb T)$ we have
 \begin{equation}

\lim_{n\to+\infty}\int_0^{t} \frac 1{n}  \sum_{x\in{\mathbb I}_n}
                                                 G_x(s)
   {\mathbb E}_n\Big[\big(\widetilde r_x^{(n)}(s) \big)^2-\big(\widetilde p_x^{(n)}(s) \big)^2\Big]
                                                 \mathrm{d} s=0.
\end{equation}

Under Assumption ass1, for any $t>0$
\begin{equation}

\frac{1}{n+1}\sup_{s\in[0,t]}\sum_{x\in{\mathbb I}_n}\Big\{\big(\overline r_x^{(n)} (s)\big)^2+\big(\overline
p_x^{(n)}(s)\big)^2\Big\}\lesssim 1,\qquad n\geqslant1.
\end{equation}
In addition,
for any $t>0$ we have
\begin{equation}

n\sum_{x\in{\mathbb I}_n}\int_0^t \big(\overline
p_x^{(n)}(s)\big)^2\mathrm{d} s\lesssim 1,\qquad n\geqslant1.
\end{equation}

Under Assumption ass1, 

for any $t\geqslant0$ we have
\begin{equation}

\sup_{s\in[0,t],\,n\geqslant1}\bigg\{\frac{1}{n+1}\sum_{x\in{\mathbb I}_n}\overline{\cal
    E}_x^{(n)}(s)\bigg\}<+\infty.
\end{equation}

The following  holds: for any $t\geqslant0$
  \begin{itemize}
  \item[(i)] \emph{(Momentum correlations)}
  \begin{equation}
  \lim_{n\to\infty} \mathbb{E}_n\left[ \int_0^t  p_{0}(s) p_{1}(s)\mathrm{d} s\right] = 0, \qquad   \lim_{n\to\infty} \mathbb{E}_n\left[ \int_0^t  p_{n-1}(s) p_{n}(s)\mathrm{d} s\right] = 0. 
\end{equation}

\item[(ii)] \emph{(Boundary correlations)}
  \begin{equation}
 \bigg| \mathbb{E}_n\left[ \int_0^t p_{0}(s) r_1(s) \mathrm{d} s\right] \bigg|\lesssim
    \frac{1}{\sqrt{n}}, 
 \qquad \bigg|\mathbb{E}_n\left[ \int_0^t p_{n}(s) r_n(s) \mathrm{d} s\right]\bigg|\lesssim
    \frac{1}{\sqrt{n}} , \qquad n\geqslant1. 
\end{equation}
\item[(iii)] \emph{(Boundary stretches)}
  \begin{equation}
  \left|\mathbb{E}_n\left[ \int_0^t r_1(s)\mathrm{d} s\right]\right|\lesssim
    \frac{1}{\sqrt{n}},   \qquad \left|\mathbb{E}_n\left[ \int_0^t \big(r_n(s) -\overline\tau_+\big)\mathrm{d} s\right]\right|\lesssim
    \frac{1}{\sqrt{n}},  \qquad n\geqslant 1.  
\end{equation}
\item[(iv)] \emph{(Boundary temperatures, part I)} for any $ n\geqslant1$
  \begin{equation}

 \left| \mathbb{E}_n\left[   \int_0^t  \left(T_--p_{0}^2(s) \right)\mathrm{d}
  s\right] \right|\lesssim \frac{1}{\sqrt n},\qquad    \left|\mathbb{E}_n\left[   \int_0^t  \left(T_+-p_{n}^2(s) \right)\mathrm{d}
  s\right]\right| \lesssim \frac{1}{\sqrt n}.  
 \end{equation}
\item[(v)] \emph{(Mechanical energy at the boundaries, part I)}
  \begin{equation}

    \mathbb{E}_n\left[ \int_0^t \left(r_1^2(s) + r_n^2(s)\right)
      \mathrm{d} s\right] \lesssim 1, \qquad n\geqslant1.
  \end{equation}
\item[(vi)] \emph{(Boundary currents)}
  \begin{equation}

      \lim_{n\to\infty}    \mathbb{E}\left[   \int_0^t  j_{0,1}(s)
      \mathrm{d} s\right]  = 0, \qquad \lim_{n\to\infty}    \mathbb{E}\left[   \int_0^t  j_{n-1,n}(s)
      \mathrm{d} s\right]  = 0.
  \end{equation}
\item[(vii)] \emph{(Mechanical energy at the boundaries, part II) :}  at the left boundary point
  \begin{equation}
  \left|\mathbb{E}_n\left[ \int_0^t \Big(r_1^2(s)-T_-\Big) \mathrm{d} s\right]\right|\lesssim
    \frac{1}{\sqrt{n}}, \qquad n\geqslant 1  
\end{equation}
and at the right boundary point
\begin{equation}   
 \left|\mathbb{E}_n\left[ \int_0^t \Big(r_n^2(s)-\overline\tau_+^2-T_+\Big)\mathrm{d} s\right] \right|\lesssim
    \frac{1}{\sqrt{n}}, \qquad n\geqslant 1. 
\end{equation}
\item[(viii)] \emph{(Boundary temperatures, part II)}
\begin{equation}

  \sum_{x=0,n}T_x\mathbb{E}_n\left[   \int_0^t  \left(T_x-p_{x}^2(s) \right)\mathrm{d}
  s\right] \lesssim \frac{1}{n},\qquad

\,n\geqslant1.
 \end{equation}
 \end{itemize}
